query SearchAirportInfo($searchTerm: String) {
  searchAirportInfo(searchTerm: $searchTerm) {
    count
    listOfCities {
      airportCode
      airportName
       airportFullName
      cityCode
      cityName
      cityType
      countryCode
      region
      timeZone
    }
    searchTerm
  }
}
